[{"order":1,"type":"heading","text":"Unit Testing ViewModels in Xamarin (NUnit, xUnit, Moq)"},{"order":2,"type":"paragraph","text":"Unit testing ViewModels is a crucial part of developing maintainable Xamarin.Forms applications using the MVVM (Model-View-ViewModel) pattern. By isolating the business logic from the UI, you can write robust tests using NUnit or xUnit along with Moq for mocking dependencies."},{"order":3,"type":"subheading","text":"Prerequisites and Setup"},{"order":4,"type":"paragraph","text":"To get started, your solution should have a core project containing your ViewModels and a dedicated unit test project. Install the following NuGet packages into your test project:"},{"order":5,"type":"bullet_point","text":"NUnit or xUnit (Test framework)"},{"order":6,"type":"bullet_point","text":"Moq (Mocking framework)"},{"order":7,"type":"bullet_point","text":"Xamarin.Mocks or Device.Init() setup for handling Xamarin.Forms specific dependencies like Device.BeginInvokeOnMainThread."},{"order":8,"type":"subheading","text":"Example ViewModel"},{"order":9,"type":"paragraph","text":"Consider a simple ViewModel that depends on an IUserService to fetch user data and updates a property."},{"order":10,"type":"code","text":"public class ProfileViewModel : INotifyPropertyChanged
{
    private readonly IUserService _userService;
    private string _userName;

    public string UserName
    {
        get => _userName;
        set
        {
            _userName = value;
            PropertyChanged?.Invoke(this, new PropertyChangedEventArgs(nameof(UserName)));
        }
    }

    public ICommand LoadUserCommand { get; }

    public ProfileViewModel(IUserService userService)
    {
        _userService = userService;
        LoadUserCommand = new Command(async () => await LoadUserAsync());
    }

    public async Task LoadUserAsync()
    {
        var user = await _userService.GetUserAsync();
        UserName = user.Name;
    }

    public event PropertyChangedEventHandler PropertyChanged;
}"},{"order":11,"type":"subheading","text":"Writing the Unit Test with NUnit and Moq"},{"order":12,"type":"paragraph","text":"We can now write a unit test to verify that calling LoadUserCommand correctly invokes the service and updates the UserName property."},{"order":13,"type":"code","text":"[TestFixture]
public class ProfileViewModelTests
{
    private Mock<IUserService> _userServiceMock;
    private ProfileViewModel _viewModel;

    [SetUp]
    public void Setup()
    {
        _userServiceMock = new Mock<IUserService>();
        _viewModel = new ProfileViewModel(_userServiceMock.Object);
    }

    [Test]
    public async Task LoadUserCommand_UpdatesUserName_WhenServiceSucceeds()
    {
        // Arrange
        var testUser = new User { Name = "John Doe" };
        _userServiceMock.Setup(s => s.GetUserAsync()).ReturnsAsync(testUser);

        // Act
        await _viewModel.LoadUserAsync();

        // Assert
        Assert.AreEqual("John Doe", _viewModel.UserName);
        _userServiceMock.Verify(s => s.GetUserAsync(), Times.Once);
    }
}"},{"order":14,"type":"subheading","text":"Best Practices"},{"order":15,"type":"bullet_point","text":"Always mock external services and navigation abstractions to keep tests fast and isolated."},{"order":16,"type":"bullet_point","text":"Use ReactiveUI or CommunityToolkit.Mvvm features carefully, ensuring dependency injection is utilized for platform-specific APIs."}]
